// Validate booking payload and format currency & times
const body = $input.item.json.body || $input.item.json;
const booking = body.data || body;

if (!booking.clientName || !booking.clientPhone || !booking.appointmentDate) {
  throw new Error('Malformed booking payload: missing required contact or date fields.');
}

return {
  json: {
    bookingId: booking.id || 'N/A',
    clientName: booking.clientName,
    clientEmail: booking.clientEmail,
    clientPhone: booking.clientPhone,
    instagramHandle: booking.instagramHandle || 'Not provided',
    serviceName: booking.serviceName || 'The Signature Russian Dry Mani',
    addons: (booking.addons || []).join(', ') || 'None',
    appointmentDate: booking.appointmentDate,
    startTime: booking.startTime,
    totalPrice: booking.totalPrice || 110,
    depositAmount: booking.depositAmount || 35,
    depositStatus: booking.depositStatus || 'pending',
    studioAddress: 'Bay Ridge, Brooklyn, NY 11209 (Private Atelier)',
    studioPhone: '+1 (929) 625-7273'
  }
};

